import java.io.*;

public class Main {

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

        int n = (int) readLong(in);

        // distancias ao quadrado: maximo possivel = 2 * 10^12 (X^R, Y^R <= 10^6),
        // universo 2^42 - 1 cobre com folga; profundidade = 42
        final long UNIVERSE = (1L << 42) - 1;

        int maxNodes = 42 * n + 100;
        int[] lc = new int[maxNodes];
        int[] rc = new int[maxNodes];
        int[] cnt = new int[maxNodes];
        for (int i = 0; i < maxNodes; i++) { lc[i] = -1; rc[i] = -1; }
        int nodeCount = 1; // no 0 = raiz

        StringBuilder sb = new StringBuilder(n * 8 + 16);
        long prevP = 0;

        for (int k = 0; k < n; k++) {
            long x = readLong(in) + prevP;
            long y = readLong(in) + prevP;
            long d = x * x + y * y;

            // quantos valores ja inseridos sao <= d
            long p = 0;
            int cur = 0;
            long lo = 0, hi = UNIVERSE;
            while (true) {
                if (d >= hi) { p += cnt[cur]; break; }
                long mid = (lo + hi) >>> 1;
                if (d <= mid) {
                    cur = lc[cur];
                    if (cur == -1) break;
                    hi = mid;
                } else {
                    if (lc[cur] != -1) p += cnt[lc[cur]];
                    cur = rc[cur];
                    if (cur == -1) break;
                    lo = mid + 1;
                }
            }

            sb.append(p).append('\n');

            // insere d na arvore de segmentos dinamica (multiconjunto)
            cur = 0; lo = 0; hi = UNIVERSE;
            cnt[0]++;
            while (lo < hi) {
                long mid = (lo + hi) >>> 1;
                if (d <= mid) {
                    if (lc[cur] == -1) lc[cur] = nodeCount++;
                    cur = lc[cur];
                    hi = mid;
                } else {
                    if (rc[cur] == -1) rc[cur] = nodeCount++;
                    cur = rc[cur];
                    lo = mid + 1;
                }
                cnt[cur]++;
            }

            prevP = p;
        }

        System.out.print(sb);
        System.out.flush();
    }

    private static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != -1 && c != '-' && (c < '0' || c > '9')) c = in.read();
        if (c == -1) return 0;
        boolean neg = (c == '-');
        if (neg) c = in.read();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = in.read();
        }
        return neg ? -v : v;
    }
}
